const DayChart = ({ children }: { children: ReactNode }) => (
  <ScatterChart
    margin={margin}
    style={{ width: '100%', minWidth: '700px', maxWidth: '900px', height: '60px' }}
    responsive
  >
    {children}
    <RechartsDevtools />
  </ScatterChart>
);

const BubbleChart = ({ defaultIndex }: { defaultIndex?: TooltipIndex }) => {
  return (
    <div style={{ width: '100%', maxWidth: '900px' }}>
      <DayChart>
        <BubbleAxes day="Sunday" />
        <Bubbles data={data01} />
        <MyTooltip defaultIndex={defaultIndex} />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Monday" />
        <Bubbles data={data02} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Tuesday" />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Wednesday" />
        <Bubbles data={data02} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Thursday" />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Friday" />
        <Bubbles data={data02} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Saturday" showXTicks />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>
    </div>
  );
};

export default BubbleChart;
